  // ── 2. ANALYSING ────────────────────────────────────────────────────────
  // L'ÉCRAN NE MONTRE QUE LE CHEMIN MINIMAL VERS UN CHART JOUABLE (Louis,
  // 2026-08-07 : « tu me changes l'écran de chargement pour juste m'afficher
  // ces étapes-là »). Cinq lignes, exactement les cinq étapes que
  // pipeline.analyze_steps traverse avant de rendre le chart brut.
  //
  // Ce qui a été RETIRÉ, et pourquoi. L'ancienne liste avait six lignes en
  // anglais dont trois mensongères : « Hearing the harmony » attendait la clé,
  // qui n'arrivait qu'à la toute fin ; « Sketching the chords » et « Naming
  // the chords — music-x-lab » décrivaient une passe brouillon suivie d'une
  // passe fine qui n'existent plus dans harmonia_min (il n'y a qu'un
  // re-décodage) ; les champs musx_fold / musx_n_folds ne sont jamais peuplés
  // par ce serveur, donc le cercle des quintes et le « fold k/N » étaient du
  // code mort. Les sections et l'analyse harmonique — 96 à 98 % du temps
  // total, mesuré — ne sont plus une étape d'attente : elles tournent APRÈS
  // l'ouverture du chart.
  // STAGES survit UNIQUEMENT pour nommer l'étape en échec sur l'écran
  // d'erreur (UI refresh 2026-08-08, §5) — l'affichage de progression est
  // maintenant renderLoading/paintLoading, piloté par `phase`, pas par ces
  // lignes. Indexé par job.stage (1 audio · 2 battues · 3 posteriors ·
  // 4 accords · 5 grille).
export const STAGES=[
    {k:"l’audio"},
    {k:"le tempo et les mesures"},
    {k:"l’écoute des accords"},
    {k:"le calage sur les temps"},
    {k:"la grille"},
  ];
export async function startAnalysis(url, title){
    S.job={title:title||"", stage:0, phase:"listening", error:null, file:null};
    go("analysing");
    try{
      // 2026-07-17: boundary-segmentation A/B override, carried on the page
      // URL (?seg=musx or ?seg=nnls) so re-analyzing the same song from an
      // iPhone home-screen bookmark can force either mode without a server
      // restart. No UI toggle yet — URL param only.
      const _seg=new URLSearchParams(location.search).get("seg");
      const _body=(_seg==="musx"||_seg==="nnls") ? {url, seg_source:_seg} : {url};
      const r=await api.post("/api/analyze",_body);
      if(r.error){ S.job.error=r.error; go("analysing"); return; }
      pollJob(r.job_id);
    }catch(e){ S.job.error=String(e); go("analysing"); }
  }
  // ── Mic access diagnostics (2026-07-21) ───────────────────────────────────
  // getUserMedia needs a SECURE context (https:// or http://localhost) — on
  // any other origin (e.g. a Tailscale IP over plain http, which is how this
  // app is normally reached from a phone) most browsers don't even show a
  // permission prompt: navigator.mediaDevices is simply undefined, so the old
  // code's blanket "Microphone access denied" was actively misleading (it
  // wasn't a user denial at all). Surface the REAL cause instead of guessing.
  // L'adresse qui a le droit au micro (tailscale serve, posé le 2026-08-20) :
  // le MÊME serveur, le même :7772, mais derrière un vrai certificat. Écrite
  // en dur parce qu'elle ne se dérive pas d'une IP Tailscale (100.x en http),
  // et parce que c'est précisément l'information actionnable à afficher.
export const HTTPS_HOST="https://louiss-macbook-air.tail87ced3.ts.net:8443";
export const micDispo=()=>!!(window.isSecureContext && navigator.mediaDevices
                        && navigator.mediaDevices.getUserMedia);
export function requestMic(){
    if(!micDispo()){
      const e=new Error("insecure-context");
      e.harmReason="insecure"; throw e;
    }
    return navigator.mediaDevices.getUserMedia({audio:true});
  }
export function micErrorMessage(e){
    if(e && e.harmReason==="insecure")
      return "Le micro demande une adresse https — ouvre "+HTTPS_HOST+" (même app).";
    if(e && e.name==="NotAllowedError") return "Microphone permission was denied — check the site settings.";
    if(e && e.name==="NotFoundError") return "No microphone found on this device.";
    return "Could not access the microphone ("+((e&&e.name)||String(e))+")";
  }
  // ── Mic recording (2026-07-20) ────────────────────────────────────────────
export async function startRecordAnalysis(blob, title){
    S.job={title:title||"", stage:0, phase:"listening", error:null, file:null};
    go("analysing");
    try{
      const fd=new FormData();
      fd.append("audio", blob, "recording.webm");
      if(title) fd.append("title", title);
      const r=await fetch("/api/record-analyze", {method:"POST", body:fd}).then(x=>x.json());
      if(r.error){ S.job.error=r.error; go("analysing"); return; }
      pollJob(r.job_id);
    }catch(e){ S.job.error=String(e); go("analysing"); }
  }
export function renderRecord(){
    const w=screenWrap();
    w.appendChild(appBar(null,"Enregistrer","library"));
    const body=el("div","flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:22px;padding:24px;");
    const timer=el("div",`font:700 44px ${UI};font-variant-numeric:tabular-nums;color:${T.ink};`,"0:00");
    const hint=el("div",`font:500 13px ${UI};color:${T.faint};text-align:center;max-width:280px;`,"Tape pour enregistrer. Joue ou chante — on en tire les accords.");
    const btn=el("button",`width:88px;height:88px;border-radius:50%;border:none;background:${T.accent};color:#fff;font:700 15px ${UI};cursor:pointer;box-shadow:0 10px 26px -12px rgba(190,90,40,.55);`,"REC");
    let rec=null, chunks=[], stream=null, t0=null, timerId=null;
    const stop=()=>{
      if(timerId) clearInterval(timerId);
      if(rec && rec.state!=="inactive") rec.stop();
      if(stream) stream.getTracks().forEach(tr=>tr.stop());
    };
    btn.onclick=async()=>{
      if(rec && rec.state==="recording"){ stop(); return; }
      try{
        stream=await requestMic();
      }catch(e){ toast(micErrorMessage(e)); return; }
      chunks=[];
      rec=new MediaRecorder(stream);
      rec.ondataavailable=e=>{ if(e.data && e.data.size) chunks.push(e.data); };
      rec.onstop=()=>{
        const blob=new Blob(chunks, {type: rec.mimeType||"audio/webm"});
        if(blob.size<2000){ toast("Enregistrement trop court"); return; }
        startRecordAnalysis(blob);
      };
      rec.start();
      t0=Date.now();
      btn.textContent="STOP"; btn.style.background=T.deep;
      timerId=setInterval(()=>{ const s=Math.floor((Date.now()-t0)/1000); timer.textContent=`${(s/60|0)}:${String(s%60).padStart(2,"0")}`; },500);
    };
    body.appendChild(timer); body.appendChild(btn); body.appendChild(hint);
    w.appendChild(body);
    return w;
  }
  // Le sondage alimente l'ÉCRAN DE CHARGEMENT (UI refresh 2026-08-08, §5) :
  // `phase` (listening → decoding → raw → sections → done) pilote
  // paintLoading, et `raw_model` — un vrai ChartModel — est rendu SUR PLACE
  // par le même chemin loadModel/buildIReal que le chart final, ce qui rend
  // le passage brut→final invisible. On n'emmène plus Louis automatiquement
  // vers le chart : le chart brut est lisible dans l'écran de chargement et
  // le bouton « Open the chart » arrive avec `done`. Un chart ouvert DEPUIS
  // LA BIBLIOTHÈQUE pendant qu'un job le raffine garde l'ancien chemin
  // (liseré S.refining + rechargement applyRefinement).
export async function pollJob(id){
    try{
      const j=await api.get("/api/job/"+id);
      if(!S.job && !S.refining) return;
      if(S.job){
        Object.assign(S.job, j);   // phase, raw_model, n_bars, sections_found…
        if(j.title) S.job.title=j.title;
        S.job.id=id;               // paintLoading en a besoin pour la sortie
      }                            // anticipée vers le chart (voir plus bas)
      const file=(j.chart_url||j.url||"").replace("/chart/","");
      if(file && S.job){
        S.job.file=file;
        // Le dossier qu'il a choisi PENDANT l'attente n'avait pas encore de
        // chart à ranger : on l'applique dès que la clé existe.
        if(S.job.dossier && !S.job._range){ S.job._range=true; ranger(file, S.job.dossier); }
      }
      if(j.status==="error"){
        if(S.job){ S.job.error=j.error||"L’analyse a échoué"; paintLoading(); }
        S.refining=null; return;
      }
      const onChart = S.screen==="chart" && S.model && S.model.file===file;
      if(j.status==="done"){
        S.refining=null;
        if(onChart) applyRefinement(file, j);          // recharge sous ses yeux
        else if(S.screen!=="analysing" && S.model && S.model.file===file) S.refineReady=file;
        if(S.screen==="analysing") paintLoading();
        paintChartRefining();
        return;
      }
      if(file) S.refining={file, id, what:j.refining||[]};
      if(S.screen==="analysing") paintLoading();
      else paintChartRefining();
      setTimeout(()=>pollJob(id), 1200);
    }catch(e){ setTimeout(()=>pollJob(id), 2000); }
  }
  // Le chart raffiné remplace celui à l'écran SANS toucher à l'audio : le
  // lecteur n'est recréé que si `S.audioUrl` change (voir mountTransport), et
  // l'url est la même — donc si Louis a lancé le son, il continue.
  // Une seule chose peut être perdue : un verrou d'accord en cours d'édition.
  // Donc on ne recharge pas par-dessus une session d'annotation — on pose une
  // pastille et il décide.
export async function applyRefinement(file, j){
    if((S.pending&&S.pending.length) || S.mode!=="read" || S.mergeMode){
      S.refineReady=file; paintChartRefining(); return;
    }
    try{
      const m=await api.get("/api/chart-model/"+file);
      const chrome=S.chartChrome, t=S.playTime;
      loadModel(m);
      S.chartChrome=chrome; S.playTime=t;
      S.refineReady=null;
      go("chart",{push:false});
    }catch(e){ /* le chart brut reste affiché, il est valide */ }
  }
  // ── the two-phase loading screen (UI refresh 2026-08-08, §5 / design 2b) ──
  // musx returns the whole decode at once, so bars do NOT trickle in. There
  // is a genuine wait, then the RAW CHART appears complete (one section, no
  // letters), then the letters fold in server-side over the same grid.
  // The trick that makes the hand-off invisible: phase "raw" hands the shell
  // a real ChartModel, so we call the SAME loadModel() + buildIReal() the
  // final chart uses. renderChordPreview() and drawCircleOfFifths() are
  // retired by this — the preview inferred bars from tempo/4 and never lined
  // up with the chart that opened after it.
export const PHASE_COPY={
    listening:["listening to the track",      "finding the beat"],
    decoding: ["reading the harmony",         "this is the long part — a minute or so on a new song"],
    head:     ["the first bars, already",     "les premières mesures pendant que le reste se calcule"],
    raw:      ["the chart, bar by bar",       "no letters yet — you can already play along"],
    sections: ["finding the sections",        "grouping the repeats into A, B, C…"],
    done:     ["ready",                       ""]
  };
export function renderLoading(){
    const w=screenWrap();

    const bar=el("div",
      `flex:0 0 auto;display:flex;align-items:center;gap:12px;`+
      `padding:calc(6px + env(safe-area-inset-top)) 14px 12px;background:${T.paper};`);
    bar.appendChild(kitIcon("‹", ()=>{ S.job=null; go("library"); }, "Back"));
    const tw=el("div","flex:1;min-width:0;");
    const title=el("div",
      `font:italic 600 19px ${SERIF};color:${T.ink};`+
      `overflow:hidden;text-overflow:ellipsis;white-space:nowrap;`);
    const sub=el("div",`font:500 13px ${UI};color:${T.faint};margin-top:2px;`);
    tw.appendChild(title); tw.appendChild(sub); bar.appendChild(tw); w.appendChild(bar);

    /* Two segments, not one bar: the wait and the sectioning are different
       kinds of work, and a single bar that jumps from 40% to 100% when the
       chart appears reads as a lie. */
    const prog=el("div",`flex:0 0 auto;padding:0 14px 14px;background:${T.paper};`);
    const segs=el("div","display:flex;gap:5px;");
    const s1=el("div",`flex:1;height:6px;border-radius:3px;background:${T.line};overflow:hidden;`);
    const s1f=el("div",`width:0%;height:100%;background:${T.amber};transition:width .5s ease;`);
    const s2=el("div",`flex:1;height:6px;border-radius:3px;background:${T.line};overflow:hidden;`);
    const s2f=el("div",`width:0%;height:100%;background:${T.accent};transition:width .5s ease;`);
    s1.appendChild(s1f); s2.appendChild(s2f); segs.appendChild(s1); segs.appendChild(s2);
    prog.appendChild(segs);
    const meta=el("div",
      `display:flex;justify-content:space-between;margin-top:8px;font:500 13px ${UI};color:${T.faint};`);
    prog.appendChild(meta); w.appendChild(prog);

    const body=el("div",`flex:1;min-height:0;overflow-y:auto;padding:0 10px;background:${T.paper};`);
    body.className="ap-scroll"; w.appendChild(body);

    const foot=el("div",
      `flex:0 0 auto;padding:14px 14px calc(14px + env(safe-area-inset-bottom));background:${T.paper};`);
    w.appendChild(foot);

    S._load={title, sub, s1f, s2f, meta, body, foot, shown:null, shownBars:0};
    paintLoading();
    return w;
  }
/* « Dans quel dossier le ranger ? », posé PENDANT l'analyse (Louis,
   2026-09-18). Le moment est le bon : il vient de lancer le morceau, il sait
   pourquoi il l'a pris, et il a une minute à attendre. Après coup il faudrait
   rouvrir la bibliothèque, entrer en mode Édition et le chercher.
   Le choix est gardé sur le job et appliqué quand le chart existe — avant,
   il n'a pas de clé à ranger. */
function choixDossier(){
    const j=S.job; const f=loadFolders();
    const w=el("div","display:flex;flex-direction:column;gap:7px;");
    w.appendChild(el("div",
      `font:600 11px ${UI};letter-spacing:.08em;text-transform:uppercase;color:${T.faint};`,
      "dans quel dossier le ranger ?"));
    const row=el("div","display:flex;gap:6px;flex-wrap:wrap;");
    const pose=(nom)=>{
      const on=(j.dossier||null)===nom;
      const b=el("button",
        `border:1px solid ${on?T.deep:T.line};border-radius:18px;background:${on?T.deep:T.card};`+
        `color:${on?"#fff":T.ink};font:600 12.5px ${UI};padding:7px 12px;min-height:38px;`+
        `cursor:pointer;-webkit-tap-highlight-color:transparent;`, nom||"Hors dossier");
      b.onclick=()=>{ j.dossier=nom; if(j.file) ranger(j.file, nom); paintLoading(); };
      row.appendChild(b);
    };
    pose(null);
    for(const nom of (f.order||[])) pose(nom);
    const plus=el("button",
      `border:1px dashed ${T.line};border-radius:18px;background:transparent;color:${T.faint};`+
      `font:600 12.5px ${UI};padding:7px 12px;min-height:38px;cursor:pointer;`, "+ nouveau");
    plus.onclick=()=>{
      const nom=(prompt("Nom du dossier")||"").trim().slice(0,80);
      if(!nom) return;
      j.dossier=nom; if(j.file) ranger(j.file, nom); paintLoading();
    };
    row.appendChild(plus);
    w.appendChild(row);
    return w;
  }

export function paintLoading(){
    const L=S._load, j=S.job;
    if(!L || !j || S.screen!=="analysing") return;
    const phase=j.phase||"listening";

    L.title.textContent=j.title||"your song";

    if(j.error){
      L.sub.textContent="something went wrong";
      clear(L.body);
      const card=el("div",
        `margin:18px 4px;background:${T.card};border:1px solid ${T.line};`+
        `border-radius:${SZ.radiusLg}px;padding:20px;`);
      card.appendChild(el("div",`font:600 15px ${UI};color:${T.accent};margin-bottom:6px;`,"That didn't work"));
      // STAGES names the step that broke — the one thing the old five-line
      // screen still had to offer.
      card.appendChild(el("div",`font:italic 13px ${SERIF};color:${T.faint};margin-bottom:8px;`,
        "échec pendant : "+(STAGES[Math.max(0,Math.min(STAGES.length-1,(j.stage||1)-1))].k)));
      card.appendChild(el("div",`font:500 13px/1.5 ${UI};color:${T.faint};`, j.error));
      L.body.appendChild(card);
      clear(L.foot);
      L.foot.appendChild(kitButton("Back to library", ()=>{ S.job=null; go("library"); },
        {height:SZ.primary, grow:true, state:"on"}));
      return;
    }

    const copy=PHASE_COPY[phase]||PHASE_COPY.listening;
    L.sub.textContent=copy[0];

    const done = phase==="done";
    const hasRaw = (phase==="head" || phase==="raw" || phase==="sections" || done)
                   && j.raw_model;
    // "head" : on a des accords à l'écran mais la passe complète tourne encore
    // — la barre ne doit pas annoncer une étape terminée.
    L.s1f.style.width = phase==="head" ? "62%"
                      : (hasRaw ? "100%" : (phase==="decoding" ? "62%" : "18%"));
    if(hasRaw) L.s1f.style.background=T.green;
    L.s2f.style.width = done ? "100%" : (phase==="sections" ? "45%" : "0%");
    if(done) L.s2f.style.background=T.green;

    clear(L.meta);
    if(hasRaw && j.n_bars){
      const a=el("div","");
      a.appendChild(el("span",`color:${done?T.green:T.ink};font-weight:700;`, j.n_bars+" bars"));
      a.appendChild(el("span","", done ? " · "+(j.sections_found||1)+" section"+((j.sections_found||1)>1?"s":"") : " decoded"));
      L.meta.appendChild(a);
    } else {
      L.meta.appendChild(el("span","", copy[1]));
    }
    // Dire l'étape RÉELLE : pendant l'aperçu on décode encore le morceau, on
    // ne cherche pas les sections (2026-08-18).
    if(hasRaw && !done) L.meta.appendChild(el("span","",
      phase==="head" ? "le reste se décode…" : "finding the sections…"));

    /* ── the body ──────────────────────────────────────────────────────────
       Before the raw chart: a quiet waiting state, NOT a fake grid. After it:
       the real chart, rendered by the real code path. */
    if(!hasRaw){
      if(L.shown!=="wait"){
        clear(L.body);
        const wrap=el("div",
          `margin:34px 4px;display:flex;flex-direction:column;align-items:center;gap:14px;text-align:center;`);
        wrap.appendChild(el("div",
          `width:34px;height:34px;border-radius:50%;border:2px solid ${T.line};`+
          `border-top-color:${T.accent};animation:ap-spin .8s linear infinite;`));
        wrap.appendChild(el("div",`font:600 15px ${UI};color:${T.ink};`, copy[0]));
        wrap.appendChild(el("div",
          `font:italic 13.5px/1.6 ${SERIF};color:${T.faint};max-width:280px;`, copy[1]));
        L.body.appendChild(wrap);
        L.shown="wait";
      }
      clear(L.foot);
      L.foot.appendChild(choixDossier());
      return;
    }

    // Le chart de tête (2026-08-18) arrive AVANT le brut et n'a que ses ~16
    // premières mesures : il faut donc re-rendre quand le brut le remplace,
    // sinon l'écran resterait sur l'aperçu. `shownBars` est le témoin.
    const nb = j.raw_model ? (j.raw_model.nBars||0) : 0;
    if(j.raw_model && (L.shown!=="chart" || L.shownBars!==nb)){
      clear(L.body);
      loadModel(j.raw_model);          // the real path — same cells as the final chart
      const head=el("div","display:flex;align-items:center;gap:8px;margin:0 4px 8px;");
      head.appendChild(el("div",
        `font:600 11px ${UI};letter-spacing:.08em;text-transform:uppercase;color:${T.faint};`,
        phase==="head" ? "aperçu · les premières mesures" : "raw chart · no letters yet"));
      head.appendChild(el("div",`flex:1;height:1px;background:${T.line};`));
      L.body.appendChild(head);
      L.body.appendChild(buildIReal());
      L.body.appendChild(kitLegend(T.green, phase==="head"
        ? "le reste du morceau se décode — ces mesures peuvent encore bouger"
        : "every bar written out — you can already play along"));
      L.shown="chart"; L.shownBars=nb;
    }

    clear(L.foot);
    // SORTIE ANTICIPÉE (Louis, 2026-08-09 : « on devrait au moins avoir le raw
    // chart dispo en interactif avec les annotate en attendant que les sections
    // se fassent »). Mesuré le même jour : les sections coûtent 160 s sur un
    // morceau de 4 min, dont 0,07 s d'algorithme — le reste est demucs (92 s)
    // + pyin (69 s), deux modèles qui tournent dans le thread du job. Le chart
    // brut, lui, est DÉJÀ écrit sur disque au premier yield de `analyze_steps`
    // (server._run_job écrit `dest` avant de distinguer raw/final), donc
    // /api/chart-model le sert immédiatement.
    //
    // Toute la machinerie d'aval existait déjà et n'est pas touchée : `S.refining`
    // pose le liseré « Sections et gamme en cours — joue, le chart se mettra à
    // jour tout seul », `applyRefinement` échange le modèle sans recréer le
    // lecteur audio, et il s'abstient si une annotation est en cours (il pose
    // « Recharger » à la place). Il ne manquait QUE la porte : le bouton
    // n'apparaissait qu'à `done`.
    // `j.file` : le chart de tête ne pose pas de `chart_url`, donc pas de
    // bouton — il ouvrirait un fichier qui n'est pas encore écrit.
    if(done || (j.raw_model && j.file)){
      const early = !done;
      // `grow:true` pose flex:1, qui ne veut rien dire dans un bloc : le
      // bouton principal de cet écran était en fait à la largeur de son texte.
      // On lui donne une ligne flex, et la légende reste en dessous.
      const row=el("div","display:flex;");
      row.appendChild(kitButton(early ? "Play it now" : "Open the chart", ()=>{
        const f=j.file;
        // l'ordre compte : pollJob s'arrête si S.job ET S.refining sont nuls
        if(early && f) S.refining={file:f, id:j.id, what:j.refining||[]};
        S.job=null;
        openChart(f);
      }, {height:SZ.primary, grow:true, state:"on"}));
      L.foot.appendChild(row);
      if(early){
        L.foot.appendChild(el("div",
          `font:italic 12px ${SERIF};color:${T.faint};text-align:center;margin-top:7px;`,
          "les lettres arrivent toutes seules pendant que tu joues"));
      }
    } else {
      const busy=el("div",
        `height:${SZ.primary}px;border-radius:${SZ.radiusLg}px;border:1px solid ${T.line};`+
        `background:${T.card};display:flex;align-items:center;justify-content:center;gap:10px;`+
        `font:600 15px ${UI};color:${T.faint};`);
      busy.appendChild(el("div",
        `width:14px;height:14px;border-radius:50%;border:2px solid ${T.line};`+
        `border-top-color:${T.accent};animation:ap-spin .7s linear infinite;`));
      busy.appendChild(el("span","",
        phase==="head" ? "Le chart complet arrive" : "Finding the sections"));
      L.foot.appendChild(busy);
    }
  }

